node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  await page.goto('http://localhost:5173/sites/acme/posts', { waitUntil: 'networkidle' });
  await page.waitForSelector('text=Posts');
  await page.screenshot({ path: '/tmp/posts-page.png' });
  console.log('BODY TEXT:', await page.locator('section').innerText());
  console.log('ERRORS:', errors);
  await browser.close();
})();
"

node -e "
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage();
  const errors = [];
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', (err) => errors.push(String(err)));
  await page.goto('http://localhost:5173/sites/acme/posts', { waitUntil: 'networkidle' });
  await page.waitForSelector('h1:has-text(\"Posts\")', { timeout: 15000 }).catch((e) => console.log('h1 wait failed', e.message));
  await page.screenshot({ path: '/tmp/posts-page.png', fullPage: true });
  console.log('BODY TEXT:', await page.locator('section').innerText());
  console.log('ERRORS:', errors);
  await browser.close();
})();
"

